#!/usr/bin/env bash
# Tests for the generated-API-client postprocessors
# (hack/ts-client/postprocess.mjs, hack/go-client/postprocess.mjs).
#
# Contract under test:
#   - TS: version import inserted after the generator's "do not edit" header
#   - TS: User-Agent inserted ahead of the baseOptions spread, at its indent
#   - TS: an existing User-Agent is replaced, not duplicated
#   - TS: generated API imports are pruned to the identifiers each file uses
#   - TS: generated parameter docs keep required/default and enum cells valid
#   - TS: missing header, or neither User-Agent nor spread -> non-zero exit
#   - Go: UserAgent literal replaced with the ClientVersion expression
#   - Go: version.go written with the go:embed accessor for the package
#   - Go: missing UserAgent -> non-zero exit
#   - Go: a spec name renames api/openapi.yaml and rewrites the FILES entry
#   - Go: no spec name -> the generator's own layout is left untouched
#   - Go: a missing spec, or a FILES without the entry, fails before any write
#
# These guard a silent-failure mode: the postprocessors used GNU-only `sed -i`,
# which BSD sed rejects, so on macOS the User-Agent injection was dropped while
# generation still appeared to produce a usable client.
#
# Run with:  bash apps/hack/postprocess.test.sh
set -uo pipefail

HACK_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TMP_ROOT="$(mktemp -d)"
trap 'rm -rf "$TMP_ROOT"' EXIT

pass=0
fail=0

check() { # desc  condition-already-evaluated($?)
  local desc="$1" rc="$2"
  if [[ "$rc" -eq 0 ]]; then
    pass=$((pass + 1)); printf '  PASS  %s\n' "$desc"
  else
    fail=$((fail + 1)); printf '  FAIL  %s\n' "$desc"
  fi
}

# ── TypeScript client ───────────────────────────────────────────────────────

ts_fixture() { # dir  [with-user-agent]
  local dir="$1" with_ua="${2:-no}" ua_line=""
  mkdir -p "$dir/api" "$dir/docs"
  [[ "$with_ua" == "with-user-agent" ]] &&
    ua_line="                'User-Agent': \`stale/0.0.0\`,
"
  cat > "$dir/configuration.ts" <<EOF
/* tslint:disable */
/**
 * NOTE: This class is auto generated by OpenAPI Generator.
 * Do not edit the class manually.
 */

export class Configuration {
    constructor(param: ConfigurationParameters = {}) {
        this.baseOptions = {
            ...param.baseOptions,
            headers: {
${ua_line}                ...param.baseOptions?.headers,
            },
        };
    }
}
EOF

  cat > "$dir/api/usage-api.ts" <<'EOF'
import { DUMMY_BASE_URL, assertParamExists, setApiKeyToObject, setBasicAuthToObject, setBearerAuthToObject, setOAuthToObject, setSearchParams, serializeDataIfNeeded, toPathString, createRequestFunction, replaceWithSerializableTypeIfNeeded } from '../common';
import { BASE_PATH, COLLECTION_FORMATS, type RequestArgs, BaseAPI, RequiredError, operationServerMap } from '../base';

/** @throws {RequiredError} when a required parameter is absent. */
export function request(): RequestArgs {
  assertParamExists('request', 'organizationId', 'org-1')
  void DUMMY_BASE_URL
  void setBearerAuthToObject
  void setSearchParams
  void toPathString
  void createRequestFunction
  void BASE_PATH
  void BaseAPI
  void operationServerMap
  return {} as RequestArgs
}
EOF

  cat > "$dir/docs/UsageApi.md" <<'EOF'
let organizationId: string; //Organization ID (default to undefined)
let from: Date; //Inclusive start. (optional) (default to undefined)

|Name | Type | Description  | Notes|
|------------- | ------------- | ------------- | -------------|
| **organizationId** | [**string**] | Organization ID | defaults to undefined|
| **from** | [**Date**] | Inclusive start. | (optional) defaults to undefined|
| **granularity** | [**&#39;hour&#39; | &#39;day&#39;**]**Array<&#39;hour&#39; &#124; &#39;day&#39; &#124; &#39;11184809&#39;>** | Spacing between snapshots. | (optional) defaults to 'day'|
| **states** | **Array<&#39;creating&#39; &#124; &#39;started&#39; &#124; &#39;archived&#39; &#124; &#39;11184809&#39;>** | States to include. | (optional) defaults to undefined|
EOF
}

ts_dir="$TMP_ROOT/ts-insert"
ts_fixture "$ts_dir"
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_dir" my-client > /dev/null 2>&1
check "TS: exits 0 on generator output" $?

grep -q "^import \* as packageJson from '../package.json';$" "$ts_dir/configuration.ts"
check "TS: version import inserted" $?

# The import must land after the header, not before it.
awk '/Do not edit the class manually/{h=NR} /^import \* as packageJson/{i=NR} END{exit !(h && i && i>h)}' \
  "$ts_dir/configuration.ts"
check "TS: import placed after the generator header" $?

grep -q "^                'User-Agent': \`my-client/\${packageJson.version}\`,$" "$ts_dir/configuration.ts"
check "TS: User-Agent inserted at the spread's indent" $?

grep -q "^                \.\.\.param\.baseOptions?\.headers,$" "$ts_dir/configuration.ts"
check "TS: the baseOptions spread survives" $?

ts_replace_dir="$TMP_ROOT/ts-replace"
ts_fixture "$ts_replace_dir" with-user-agent
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_replace_dir" my-client > /dev/null 2>&1
[[ "$(grep -c "'User-Agent'" "$ts_replace_dir/configuration.ts")" -eq 1 ]]
check "TS: existing User-Agent replaced, not duplicated" $?

grep -q "my-client/\${packageJson.version}" "$ts_replace_dir/configuration.ts" &&
  ! grep -q "stale/0.0.0" "$ts_replace_dir/configuration.ts"
check "TS: replacement carries the new client name" $?

grep -q "import { DUMMY_BASE_URL, assertParamExists, setBearerAuthToObject, setSearchParams, toPathString, createRequestFunction } from '../common';" "$ts_dir/api/usage-api.ts" &&
  ! grep -q 'setApiKeyToObject\|setBasicAuthToObject\|setOAuthToObject\|serializeDataIfNeeded\|replaceWithSerializableTypeIfNeeded' "$ts_dir/api/usage-api.ts"
check "TS: unused common imports are pruned" $?

grep -q "import { BASE_PATH, type RequestArgs, BaseAPI, operationServerMap } from '../base';" "$ts_dir/api/usage-api.ts" &&
  ! grep -q '^import .*COLLECTION_FORMATS\|^import .*RequiredError' "$ts_dir/api/usage-api.ts"
check "TS: unused base imports are pruned" $?

! grep -q 'organizationId.*default to undefined\|organizationId.*defaults to undefined' "$ts_dir/docs/UsageApi.md" &&
  grep -q 'from.*optional.*default to undefined' "$ts_dir/docs/UsageApi.md"
check "TS: required docs omit undefined defaults while optional docs retain them" $?

grep -q "| \*\*granularity\*\* | \[\*\*&#39;hour&#39; &#124; &#39;day&#39;\*\*\] |" "$ts_dir/docs/UsageApi.md" &&
  ! grep -q 'granularity.*Array<\|granularity.*11184809' "$ts_dir/docs/UsageApi.md"
check "TS: scalar enum docs render one escaped union cell" $?

grep -q "| \*\*states\*\* | \*\*Array<&#39;creating&#39; &#124; &#39;started&#39; &#124; &#39;archived&#39;>\*\* |" "$ts_dir/docs/UsageApi.md" &&
  ! grep -q 'states.*11184809' "$ts_dir/docs/UsageApi.md"
check "TS: array enum docs omit the generator fallback member" $?

ts_bad_dir="$TMP_ROOT/ts-noheader"
mkdir -p "$ts_bad_dir"
echo 'export class Configuration {}' > "$ts_bad_dir/configuration.ts"
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_bad_dir" my-client > /dev/null 2>&1
[[ $? -ne 0 ]]
check "TS: missing generator header is a hard error" $?

ts_nospread_dir="$TMP_ROOT/ts-nospread"
mkdir -p "$ts_nospread_dir"
printf '/**\n * Do not edit the class manually.\n */\n\nexport class Configuration {}\n' \
  > "$ts_nospread_dir/configuration.ts"
node "$HACK_DIR/ts-client/postprocess.mjs" "$ts_nospread_dir" my-client > /dev/null 2>&1
[[ $? -ne 0 ]]
check "TS: no User-Agent and no spread is a hard error" $?

# ── Go client ───────────────────────────────────────────────────────────────

go_dir="$TMP_ROOT/go"
mkdir -p "$go_dir"
cat > "$go_dir/configuration.go" <<'EOF'
package apiclient

func NewConfiguration() *Configuration {
	cfg := &Configuration{
		DefaultHeader:    make(map[string]string),
		UserAgent:        "OpenAPI-Generator/1.0.0/go",
		Debug:            false,
	}
	return cfg
}
EOF

node "$HACK_DIR/go-client/postprocess.mjs" "$go_dir" apiclient my-go-client > /dev/null 2>&1
check "Go: exits 0 on generator output" $?

grep -q 'UserAgent:        "my-go-client/" + ClientVersion' "$go_dir/configuration.go"
check "Go: UserAgent replaced with the ClientVersion expression" $?

! grep -q 'OpenAPI-Generator/1.0.0/go' "$go_dir/configuration.go"
check "Go: generator default UserAgent gone" $?

grep -q '^package apiclient$' "$go_dir/version.go" &&
  grep -q '^//go:embed VERSION$' "$go_dir/version.go" &&
  grep -q '^var ClientVersion = strings.TrimSpace(_clientVersion)$' "$go_dir/version.go"
check "Go: version.go written with the go:embed accessor" $?

go_bad_dir="$TMP_ROOT/go-bad"
mkdir -p "$go_bad_dir"
echo 'package apiclient' > "$go_bad_dir/configuration.go"
node "$HACK_DIR/go-client/postprocess.mjs" "$go_bad_dir" apiclient my-go-client > /dev/null 2>&1
[[ $? -ne 0 ]]
check "Go: missing UserAgent is a hard error" $?

# ── Go client: control-plane spec rename ────────────────────────────────────
#
# The generator always drops its spec copy at api/openapi.yaml. A client whose
# spec describes one named API renames it, and the FILES manifest has to move
# with it or the next regeneration diffs against a name the tree no longer has.

write_go_spec_fixture() { # dir
  mkdir -p "$1/api" "$1/.openapi-generator"
  cat > "$1/configuration.go" <<'EOF'
package apiclient

func NewConfiguration() *Configuration {
	cfg := &Configuration{
		UserAgent:        "OpenAPI-Generator/1.0.0/go",
	}
	return cfg
}
EOF
  printf 'openapi: 3.0.0\n' > "$1/api/openapi.yaml"
  printf '.gitignore\napi/openapi.yaml\napi_admin.go\n' > "$1/.openapi-generator/FILES"
}

go_spec_dir="$TMP_ROOT/go-spec"
write_go_spec_fixture "$go_spec_dir"
node "$HACK_DIR/go-client/postprocess.mjs" "$go_spec_dir" apiclient my-go-client control-plane-api.yaml > /dev/null 2>&1
check "Go: exits 0 when a spec name is given" $?

[[ -f "$go_spec_dir/api/control-plane-api.yaml" && ! -e "$go_spec_dir/api/openapi.yaml" ]]
check "Go: spec copy renamed to the requested name" $?

grep -qx 'api/control-plane-api.yaml' "$go_spec_dir/.openapi-generator/FILES" &&
  ! grep -q 'api/openapi.yaml' "$go_spec_dir/.openapi-generator/FILES"
check "Go: FILES manifest entry rewritten to match" $?

go_nospec_dir="$TMP_ROOT/go-nospec"
write_go_spec_fixture "$go_nospec_dir"
node "$HACK_DIR/go-client/postprocess.mjs" "$go_nospec_dir" apiclient my-go-client > /dev/null 2>&1
[[ -f "$go_nospec_dir/api/openapi.yaml" ]] &&
  grep -qx 'api/openapi.yaml' "$go_nospec_dir/.openapi-generator/FILES"
check "Go: no spec name leaves the generator's layout untouched" $?

go_missing_dir="$TMP_ROOT/go-missing"
write_go_spec_fixture "$go_missing_dir"
rm "$go_missing_dir/api/openapi.yaml"
node "$HACK_DIR/go-client/postprocess.mjs" "$go_missing_dir" apiclient my-go-client control-plane-api.yaml > /dev/null 2>&1
rc=$?
[[ "$rc" -ne 0 ]] && grep -qx 'api/openapi.yaml' "$go_missing_dir/.openapi-generator/FILES"
check "Go: missing spec copy is a hard error, manifest left alone" $?

# Both preconditions are checked before either write: a rename that succeeded
# ahead of a failing manifest check would leave a half-renamed tree, and the
# drift diff that follows names no cause.
go_stale_dir="$TMP_ROOT/go-stale"
write_go_spec_fixture "$go_stale_dir"
printf '.gitignore\napi_admin.go\n' > "$go_stale_dir/.openapi-generator/FILES"
node "$HACK_DIR/go-client/postprocess.mjs" "$go_stale_dir" apiclient my-go-client control-plane-api.yaml > /dev/null 2>&1
rc=$?
[[ "$rc" -ne 0 ]] && [[ -f "$go_stale_dir/api/openapi.yaml" ]] &&
  [[ ! -e "$go_stale_dir/api/control-plane-api.yaml" ]]
check "Go: FILES without the entry fails before the rename" $?

printf '\n%d passed, %d failed\n' "$pass" "$fail"
[[ "$fail" -eq 0 ]]
